using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RepairLegacyLocal {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/Existing_VARCO_Repair_20261103"));
static Bounds B(GameObject g){var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var x in rr.Skip(1))b.Encapsulate(x.bounds);return b;}
static void Preview(GameObject prefab,string file){var p=new PreviewRenderUtility();var g=UnityEngine.Object.Instantiate(prefab);p.AddSingleGO(g);var b=B(g);float s=b.size.magnitude;p.camera.transform.position=b.center+new Vector3(-.9f,.55f,-1.6f)*s;p.camera.transform.LookAt(b.center);p.camera.fieldOfView=35;p.camera.nearClipPlane=.001f;p.camera.farClipPlane=100;p.camera.clearFlags=CameraClearFlags.Color;p.camera.backgroundColor=new Color(.16f,.17f,.19f);p.lights[0].intensity=1.5f;p.lights[0].transform.rotation=Quaternion.Euler(40,40,0);p.lights[1].intensity=1;p.lights[1].transform.rotation=Quaternion.Euler(340,210,0);p.ambientColor=new Color(.3f,.3f,.3f);for(int i=0;i<3;i++){p.BeginStaticPreview(new Rect(0,0,800,800));p.Render(true);var tex=p.EndStaticPreview();if(i==2)File.WriteAllBytes(file,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}p.Cleanup();}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var config=JArray.Parse(File.ReadAllText(Path.Combine(R,"repair_export_manifest.json")));var facts=new List<object>();Directory.CreateDirectory(Path.Combine(R,"PrefabBackup"));foreach(JObject a in config){string name=(string)a["name"],path=(string)a["prefabPath"],model=(string)a["repairedModelPath"];var imp=(ModelImporter)AssetImporter.GetAtPath(model);imp.materialImportMode=ModelImporterMaterialImportMode.None;imp.importAnimation=false;imp.importCameras=false;imp.importLights=false;imp.importNormals=ModelImporterNormals.Import;imp.importTangents=ModelImporterTangents.CalculateMikk;imp.meshCompression=ModelImporterMeshCompression.Off;imp.isReadable=true;imp.SaveAndReimport();
string backup=Path.Combine(R,"PrefabBackup",name+".prefab");if(!File.Exists(backup)){File.Copy(path,backup);File.Copy(path+".meta",backup+".meta");}
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);var content=PrefabUtility.LoadPrefabContents(path);var old=content.GetComponentsInChildren<MeshFilter>();if(old.Length!=1)throw new Exception("Expected single old mesh "+name);var oldBounds=B(content);old[0].sharedMesh=AssetDatabase.LoadAssetAtPath<GameObject>((string)a["modelPath"]).GetComponentInChildren<MeshFilter>().sharedMesh;var candidate=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(model));var fresh=candidate.GetComponentsInChildren<MeshFilter>();if(fresh.Length!=1)throw new Exception("Expected single candidate mesh");var cb=B(candidate);var ob=old[0].sharedMesh.bounds;var nb=fresh[0].sharedMesh.bounds;Vector3 scale=new Vector3(ob.size.x/nb.size.x,ob.size.y/nb.size.y,ob.size.z/nb.size.z);Matrix4x4 matrix=Matrix4x4.Translate(ob.center)*Matrix4x4.Scale(scale)*Matrix4x4.Translate(-nb.center);var mesh=UnityEngine.Object.Instantiate(fresh[0].sharedMesh);mesh.name=name+"_Repaired";mesh.vertices=mesh.vertices.Select(v=>matrix.MultiplyPoint3x4(v)).ToArray();var normal=matrix.inverse.transpose;mesh.normals=mesh.normals.Select(n=>normal.MultiplyVector(n).normalized).ToArray();mesh.RecalculateBounds();mesh.RecalculateTangents();string asset=Path.GetDirectoryName(model).Replace('\\','/')+"/"+name+"_Repaired.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(asset);if(existing==null)AssetDatabase.CreateAsset(mesh,asset);else{EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}old[0].sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(old[0]);var after=B(content);if((after.center-oldBounds.center).magnitude>.001f||(after.size-oldBounds.size).magnitude>.001f)throw new Exception("Bounds changed");PrefabUtility.SaveAsPrefabAsset(content,path);PrefabUtility.UnloadPrefabContents(content);UnityEngine.Object.DestroyImmediate(candidate);Preview(AssetDatabase.LoadAssetAtPath<GameObject>(path),Path.Combine(R,name+"_after.png"));facts.Add(new{name=name,prefabPath=path,repairedMesh=asset,triangles=mesh.triangles.Length/3,oldBoundsSize=new[]{oldBounds.size.x,oldBounds.size.y,oldBounds.size.z},candidateSize=new[]{cb.size.x,cb.size.y,cb.size.z},boundsPreserved=true,originalFbxPreserved=true});}
AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(R,"unity_repair_facts.json"),JsonConvert.SerializeObject(facts,Formatting.Indented));return "Repaired 8 legacy prefab meshes; originals and bounds preserved";}}
